import sys, re, math, itertools
sys.path.insert(0, '/private/tmp/tmpjnj0xuqf/pete/projects/minisql')
import minisql

d = '/private/tmp/tmpjnj0xuqf/tmp/opencode/msdb'
vals = [
    ('NULL', None), ('TRUE', True), ('FALSE', False),
    ('-2', -2), ('0', 0), ('3', 3), ('2.5', 2.5),
    ("''", ''), ("'a'", 'a'), ("'A'", 'A'), ("'ab'", 'ab'), ("'abc'", 'abc'), ("'10'", '10'),
]

def isnum(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def cmp(op, a, b):
    if a is None or b is None:
        return None
    if isnum(a) and isnum(b): pass
    elif isinstance(a, str) and isinstance(b, str): pass
    elif isinstance(a, bool) and isinstance(b, bool): pass
    else: return 'ERR'
    return {'=': a == b, '<': a < b, '<=': a <= b, '>': a > b, '>=': a >= b}[op]

def not3(x):
    return None if x is None else (not x)

def and3(a, b):
    if a is False or b is False: return False
    if a is None or b is None: return None
    return True

def in_expected(x, items):
    saw = x is None
    for it in items:
        if it is None:
            saw = True
            continue
        if x is None:
            continue
        c = cmp('=', x, it)
        if c == 'ERR':
            return 'ERR'
        if c:
            return True
    return None if saw else False

def like_expected(v, p):
    if v is None or p is None: return None
    if not isinstance(v, str) or not isinstance(p, str): return 'ERR'
    pat = ''.join('.*' if ch == '%' else '.' if ch == '_' else re.escape(ch) for ch in p)
    return re.fullmatch(pat, v, re.DOTALL) is not None

def run(expr):
    try:
        return minisql.run('SELECT %s FROM t LIMIT 1' % expr, d).rows[0][0]
    except minisql.QueryError:
        return 'ERR'
    except Exception as e:
        return '!!!%s:%s' % (type(e).__name__, e)

def norm(x):
    if x == 'ERR': return x
    if isinstance(x, bool): return ('bool', x)
    if isinstance(x, float): return ('float', x)
    if isinstance(x, int): return ('int', x)
    return x

bad = []
# IN lists of 2-3 values
for tx, vx in vals:
    for combo in itertools.product(vals, repeat=2):
        tlist = ', '.join(t for t, _ in combo)
        exp = in_expected(vx, [v for _, v in combo])
        got = run('%s IN (%s)' % (tx, tlist))
        if norm(got) != norm(exp):
            bad.append(('IN', tx, tlist, got, exp))
        expn = None if exp is None or exp == 'ERR' else (exp if exp == 'ERR' else (not exp))
        # NOT IN via not3
        if exp != 'ERR':
            expn = not3(exp)
        gotn = run('%s NOT IN (%s)' % (tx, tlist))
        if norm(gotn) != norm(expn):
            bad.append(('NOTIN', tx, tlist, gotn, expn))
# BETWEEN
for tx, vx in vals:
    for (ta, va), (tb, vb) in itertools.product(vals, repeat=2):
        lo = cmp('<=', va, vx)
        hi = cmp('<=', vx, vb)
        if lo == 'ERR' or hi == 'ERR':
            exp = 'ERR'
        else:
            exp = and3(lo, hi)
        got = run('%s BETWEEN %s AND %s' % (tx, ta, tb))
        if norm(got) != norm(exp):
            bad.append(('BETWEEN', tx, ta, tb, got, exp))
        if exp != 'ERR':
            expn = not3(exp)
        else:
            expn = 'ERR'
        gotn = run('%s NOT BETWEEN %s AND %s' % (tx, ta, tb))
        if norm(gotn) != norm(expn):
            bad.append(('NOTBETWEEN', tx, ta, tb, gotn, expn))
# LIKE
for tx, vx in vals:
    for tp, vp in vals:
        exp = like_expected(vx, vp)
        got = run('%s LIKE %s' % (tx, tp))
        if norm(got) != norm(exp):
            bad.append(('LIKE', tx, tp, got, exp))
        expn = 'ERR' if exp == 'ERR' else not3(exp)
        gotn = run('%s NOT LIKE %s' % (tx, tp))
